/**
 * @class Alloy.builtins.animation
 * A stub of Alloy's animation builtin, in the JSDuck style Alloy documents its builtins in: the
 * description sits under `@method`, and a platform-only function is chosen by a compile time
 * constant.
 */

/**
 * @property {String} HORIZONTAL
 * A direction to flip in
 */
exports.HORIZONTAL = 'horizontal';

/**
 * @method fadeIn
 * Fades in the specified view.
 * @param {Titanium.UI.View} to View to fade in.
 * @param {Number} duration Fade duration in milliseconds.
 * @param {function()} [finishCallback] Callback function, invoked after the fade completes.
 */
exports.fadeIn = function (to, duration, finishCallback) {
	to.animate({ opacity: 1, duration: duration }, finishCallback);
};

/**
 * @method flip
 * Flips from one view to another.
 * @param {Titanium.UI.View} from View to flip away from.
 * @param {Titanium.UI.View} to View to flip to.
 */
exports.flip = OS_IOS ? function (from, to) {
	from.hide();
	to.show();
} : undefined;
